$ErrorActionPreference='Stop'
$js=@'
let ws;try{
const tabs=await(await fetch("http://127.0.0.1:17447/json/list")).json();
const t=tabs.find(x=>x.url.startsWith("https://www.avito.ru/krasnoyarsk/")&&x.webSocketDebuggerUrl);
if(!t)throw Error("tab missing");
ws=new WebSocket(t.webSocketDebuggerUrl);
const answer=await Promise.race([
new Promise((ok,bad)=>{
ws.addEventListener("open",()=>{const expression="(()=>[...document.querySelectorAll('[data-marker=item]')].slice(0,50).map((el,i)=>({i,text:el.textContent.trim().replace(/\\s+/g,' ').slice(0,270),link:el.querySelector('a[href*=\"/krasnoyarsk/\"]')?.href||el.querySelector('a[href]')?.href||''})))()";ws.send(JSON.stringify({id:84,method:"Runtime.evaluate",params:{expression,returnByValue:true}}))},{once:true});
ws.addEventListener("message",e=>{let x=JSON.parse(e.data);if(x.id===84)ok(x.result?.result?.value||{error:x.error?.message})});
ws.addEventListener("error",bad,{once:true})
}),
new Promise((_,bad)=>setTimeout(()=>bad(Error("timeout")),8000))
]);
console.log(JSON.stringify(answer))
}catch(e){console.log(JSON.stringify({error:String(e).slice(0,100)}))}
if(ws)ws.close();process.exit(0)
'@
$tmp=Join-Path $env:TEMP 'pc-avito-listing-snippets-20261012.mjs'
try{[System.IO.File]::WriteAllText($tmp,$js,[System.Text.UTF8Encoding]::new($false));& node.exe $tmp}finally{Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue}
